-- Existing rows have invitation_id NULL, so they satisfy the new CHECKs.
ALTER TABLE "user_tokens" DROP CONSTRAINT "user_tokens_purpose_check";--> statement-breakpoint
ALTER TABLE "user_tokens" DROP CONSTRAINT "user_tokens_shape_check";--> statement-breakpoint
ALTER TABLE "user_tokens" ADD COLUMN "invitation_id" varchar(36);--> statement-breakpoint
ALTER TABLE "user_tokens" ADD CONSTRAINT "user_tokens_invitation_id_tenant_invitations_id_fk" FOREIGN KEY ("invitation_id") REFERENCES "public"."tenant_invitations"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "user_tokens_invitation_id_idx" ON "user_tokens" USING btree ("invitation_id") WHERE "user_tokens"."invitation_id" is not null;--> statement-breakpoint
ALTER TABLE "user_tokens" ADD CONSTRAINT "user_tokens_purpose_check" CHECK ("user_tokens"."purpose" in ('refresh', 'sign_in_link', 'step_up_link', 'invitation_link'));--> statement-breakpoint
ALTER TABLE "user_tokens" ADD CONSTRAINT "user_tokens_shape_check" CHECK (("user_tokens"."purpose" = 'refresh' and "user_tokens"."user_id" is not null and "user_tokens"."email" is null and "user_tokens"."app" is null and "user_tokens"."redirect" is null and "user_tokens"."invitation_id" is null) or ("user_tokens"."purpose" = 'sign_in_link' and "user_tokens"."user_id" is null and "user_tokens"."session_id" is null and "user_tokens"."email" is not null and "user_tokens"."app" is not null and "user_tokens"."invitation_id" is null) or ("user_tokens"."purpose" = 'step_up_link' and "user_tokens"."user_id" is not null and "user_tokens"."session_id" is not null and "user_tokens"."email" is not null and "user_tokens"."app" is not null and "user_tokens"."redirect" is null and "user_tokens"."invitation_id" is null) or ("user_tokens"."purpose" = 'invitation_link' and "user_tokens"."user_id" is null and "user_tokens"."session_id" is null and "user_tokens"."email" is not null and "user_tokens"."app" is not null and "user_tokens"."redirect" is null and "user_tokens"."invitation_id" is not null));